// Open-graph image resolver (plan #4 item 5).
//
// Social cards want a 1200×630 image; the mirrored posters are 252×378 and
// the favicon is 256×256. This returns the per-title image generated by
// scripts/og-images.mjs into public/og/<id>.jpg, or the shared default when
// no poster exists — so every title page has a correctly-sized OG image.
//
// Note: every live title gets a file at public/og/<id>.jpg from the og-images
// script (unless no poster exists, in which case the default is used).
export const OG_DEFAULT = '/og/default.jpg';
export const OG_SIZE = { w: 1200, h: 630 };

export function ogFor(movie) {
    if (!movie) return OG_DEFAULT;
    return `/og/${movie.id}.jpg`;
}